%%\ Amphibious Drone Electronics Enclosure - Transient Thermal Model
% Lumped-parameter thermal model for four suspended ESCs inside a sealed
% cylindrical PVC enclosure with acrylic end caps.
%
% IMPORTANT:
% This is a first-pass engineering model, not a validated CFD/FEA model.
% Replace the assumed values below with measured/manufacturer data.
%
% Model nodes:
%   1-4: individual ESCs
%   5:   internal air
%   6:   enclosure wall/end caps (lumped inner-surface temperature)
%
% Heat paths:
%   ESC -> internal air by convection
%   ESC -> enclosure by thermal radiation
%   Internal air -> enclosure by natural convection
%   Enclosure -> ambient by conduction through PVC/acrylic and external
%                convection to air or water
%
% Requires MATLAB R2016b or newer (script with local function).

clear; clc; close all;

%%\ 1. USER-ADJUSTABLE INPUTS

% Geometry
p.ID_in       = 2 + 23/64;       % tube inner diameter [in]
p.OD_in       = 2.5;             % tube outer diameter [in]
p.L_in        = 18;              % tube length [in]
p.cap_t_in    = 0.25;            % acrylic cap thickness [in] - ASSUMED
p.nESC        = 4;
p.esc_L_in    = 2.7;             % ESC length [in]
p.esc_W_in    = 1.1;             % ESC width [in]
p.esc_H_in    = 0.28;            % ESC thickness [in]
p.esc_end_gap_in = 0.5;          % distance from ESCs to nearest end [in]

% Electrical operating point
p.V_batt      = 14.8;             % nominal 4S battery voltage [V]
p.I_ESC       = 7.5;              % current per ESC [A]; test 5 to 10 A
p.ESC_eff     = 0.96;             % assumed ESC efficiency, not measured
p.P_other_W   = 2.0;              % all other electronics heat [W], estimate
p.I_BEC       = 0.0;              % BEC output current per ESC [A]; 0 if unused
p.V_BEC       = 5.0;              % BEC output voltage [V]
p.BEC_is_linear = true;           % set false if BEC is switching
% If linear BEC is used, approximate BEC heat per ESC as (Vbatt-VBEC)*I_BEC.
% Do NOT parallel BEC outputs unless the ESC manufacturer permits it.

% Material properties (typical starting estimates; verify actual grades)
p.k_PVC      = 0.16;              % PVC thermal conductivity [W/m-K]
p.rho_PVC    = 1400;              % PVC density [kg/m^3]
p.cp_PVC     = 900;               % PVC specific heat [J/kg-K]
p.k_acrylic  = 0.19;              % acrylic thermal conductivity [W/m-K]
p.rho_acrylic= 1180;              % acrylic density [kg/m^3]
p.cp_acrylic = 1470;              % acrylic specific heat [J/kg-K]
p.rho_air    = 1.18;              % air density [kg/m^3]
p.cp_air     = 1005;              % air specific heat [J/kg-K]

% ESC thermal properties (approximate equivalent package values)
p.m_ESC      = 0.025;             % mass of one ESC [kg] - replace if weighed
p.cp_ESC     = 900;               % effective ESC heat capacity [J/kg-K]
p.emissivity = 0.85;              % ESC surface emissivity estimate
p.h_ESC_air  = 5;                 % natural convection ESC-to-air [W/m^2-K]
p.h_air_wall = 3;                 % natural convection air-to-inner-wall [W/m^2-K]

% External conditions
p.T_air_C   = 25;                 % ambient air temperature [deg C]
p.T_water_C = 20;                 % surrounding water temperature [deg C]
p.h_ext_air = 8;                  % external natural convection in air [W/m^2-K]
p.h_ext_water = 150;              % external convection in water [W/m^2-K]
% Water coefficient depends strongly on water motion; 150 is a starting
% estimate for relatively mild water movement, not a guaranteed value.

% Simulation
p.t_end_min = 60;                 % simulation duration [minutes]
p.T_initial_C = 25;               % initial component/enclosure temperature [deg C]

%%\ 2. DERIVED GEOMETRY AND THERMAL PARAMETERS

inch = 0.0254;
p.ri = (p.ID_in*inch)/2;
p.ro = (p.OD_in*inch)/2;
p.L  = p.L_in*inch;
p.cap_t = p.cap_t_in*inch;

p.esc_L = p.esc_L_in*inch;
p.esc_W = p.esc_W_in*inch;
p.esc_H = p.esc_H_in*inch;

% Internal cylindrical volume
p.V_air = pi*p.ri^2*p.L;

% ESC total exposed surface area (rectangular-prism approximation)
p.A_ESC = 2*(p.esc_L*p.esc_W + p.esc_L*p.esc_H + p.esc_W*p.esc_H);

% Inner and outer enclosure surface areas
p.A_inner_side = 2*pi*p.ri*p.L;
p.A_outer_side = 2*pi*p.ro*p.L;
p.A_cap_inner_total = 2*pi*p.ri^2;
p.A_cap_outer_total = 2*pi*p.ro^2;
p.A_inner_total = p.A_inner_side + p.A_cap_inner_total;
p.A_outer_total = p.A_outer_side + p.A_cap_outer_total;

% PVC side-wall mass
V_PVC = pi*(p.ro^2-p.ri^2)*p.L;
m_PVC = p.rho_PVC*V_PVC;

% Two acrylic end caps (disk volume; approximate disk radius = tube OD/2)
V_caps = 2*pi*p.ro^2*p.cap_t;
m_caps = p.rho_acrylic*V_caps;

% Lumped thermal capacitances [J/K]
p.C_ESC = p.m_ESC*p.cp_ESC;                  % each ESC
p.C_air = p.rho_air*p.V_air*p.cp_air;
p.C_wall = m_PVC*p.cp_PVC + m_caps*p.cp_acrylic;

% Conduction resistance through cylindrical PVC side wall
R_PVC = log(p.ro/p.ri)/(2*pi*p.k_PVC*p.L);

% Conduction resistance through two acrylic end caps in parallel
A_cap = pi*p.ri^2;
R_caps_each = p.cap_t/(p.k_acrylic*A_cap);
R_caps_parallel = R_caps_each/2;

% Parallel conduction paths: PVC cylindrical wall and two end caps
R_cond_enclosure = 1/(1/R_PVC + 1/R_caps_parallel);

% ESC-to-air conductance
G_ESC_air = p.h_ESC_air*p.A_ESC;

% Internal air-to-wall conductance
G_air_wall = p.h_air_wall*p.A_inner_total;

% Display key derived quantities
fprintf('\n===== MODEL GEOMETRY =====\n'); %[output:5a464d4c]
fprintf('Internal diameter: %.2f mm\n',2*p.ri*1000); %[output:6f578190]
fprintf('External diameter: %.2f mm\n',2*p.ro*1000); %[output:65b9c167]
fprintf('Length: %.1f mm\n',p.L*1000); %[output:37ac61d7]
fprintf('Internal air volume: %.3f L\n',p.V_air*1000); %[output:811a16d9]
fprintf('ESC exposed area (each): %.5f m^2\n',p.A_ESC); %[output:41aae7ab]
fprintf('Assumed acrylic cap thickness: %.2f mm\n',p.cap_t*1000); %[output:86786f6f]
fprintf('PVC conduction resistance: %.3f K/W\n',R_PVC); %[output:3bfbb284]
fprintf('Two-cap conduction resistance: %.3f K/W\n',R_caps_parallel); %[output:1657dc18]

%%\ 3. SIMULATE AIR AND WATER CASES

% Case 1: external air
p_case = p;
p_case.T_ambient_C = p.T_air_C;
p_case.h_ext = p.h_ext_air;
[t_air, T_air_case] = runThermalCase(p_case, G_ESC_air, G_air_wall, ...
    R_cond_enclosure, m_PVC, m_caps);

% Case 2: external water
p_case = p;
p_case.T_ambient_C = p.T_water_C;
p_case.h_ext = p.h_ext_water;
[t_water, T_water_case] = runThermalCase(p_case, G_ESC_air, G_air_wall, ...
    R_cond_enclosure, m_PVC, m_caps);

%%\ 4. PLOTS

time_air_min = t_air/60;
time_water_min = t_water/60;

figure('Name','Air operation','Color','w'); %[output:3ea1ea2e]
plot(time_air_min,T_air_case(:,1:4),'LineWidth',1.5); hold on; %[output:3ea1ea2e]
plot(time_air_min,T_air_case(:,5),'k--','LineWidth',2); %[output:3ea1ea2e]
plot(time_air_min,T_air_case(:,6),'k:','LineWidth',2); %[output:3ea1ea2e]
grid on; xlabel('Time [min]'); ylabel('Temperature [°C]'); %[output:3ea1ea2e]
title('Transient temperatures - external air at 25°C'); %[output:3ea1ea2e]
legend('ESC 1','ESC 2','ESC 3','ESC 4','Internal air','Enclosure','Location','best'); %[output:3ea1ea2e]

figure('Name','Underwater operation','Color','w'); %[output:728a75fc]
plot(time_water_min,T_water_case(:,1:4),'LineWidth',1.5); hold on; %[output:728a75fc]
plot(time_water_min,T_water_case(:,5),'k--','LineWidth',2); %[output:728a75fc]
plot(time_water_min,T_water_case(:,6),'k:','LineWidth',2); %[output:728a75fc]
grid on; xlabel('Time [min]'); ylabel('Temperature [°C]'); %[output:728a75fc]
title('Transient temperatures - external water at 20°C'); %[output:728a75fc]
legend('ESC 1','ESC 2','ESC 3','ESC 4','Internal air','Enclosure','Location','best'); %[output:728a75fc]

figure('Name','Environment comparison','Color','w'); %[output:3121d160]
plot(time_air_min,max(T_air_case(:,1:4),[],2),'r-','LineWidth',2); hold on; %[output:3121d160]
plot(time_water_min,max(T_water_case(:,1:4),[],2),'b-','LineWidth',2); %[output:3121d160]
yline(80,'k--','80°C reference'); %[output:3121d160]
grid on; xlabel('Time [min]'); ylabel('Maximum ESC temperature [°C]'); %[output:3121d160]
title('Maximum ESC temperature: air vs. water'); %[output:3121d160]
legend('Air case','Water case','80°C reference','Location','best'); %[output:3121d160]

%%\ 5. PRINT RESULTS

fprintf('\n===== RESULTS AT %.1f MINUTES =====\n',p.t_end_min); %[output:34deee17]
fprintf('ESC heat loss per ESC (excluding BEC): %.2f W\n', ... %[output:group:3dcbc85f] %[output:59471f0c]
    p.V_batt*p.I_ESC*(1-p.ESC_eff)); %[output:group:3dcbc85f] %[output:59471f0c]
if p.BEC_is_linear %[output:group:427ea088]
    fprintf('Linear BEC heat per ESC: %.2f W\n', ... %[output:6882013a]
        max(p.V_batt-p.V_BEC,0)*p.I_BEC); %[output:6882013a]
else
    fprintf('BEC heat per ESC: not included (switching BEC; enter measured loss if known).\n');
end %[output:group:427ea088]
fprintf('Other electronics heat: %.2f W total\n',p.P_other_W); %[output:7082eee5]

printCaseResults('AIR',T_air_case,p); %[output:9d7a4dd4]
printCaseResults('WATER',T_water_case,p); %[output:169d9e33]

%%\ 6. QUICK SENSITIVITY STUDY: ESC CURRENT

currents = [5 7.5 10];
maxESC_air = zeros(size(currents));
maxESC_water = zeros(size(currents));

for k = 1:numel(currents)
    p_s = p;
    p_s.I_ESC = currents(k);
    p_s.T_ambient_C = p.T_air_C;
    p_s.h_ext = p.h_ext_air;
    [~,Ta] = runThermalCase(p_s,G_ESC_air,G_air_wall,R_cond_enclosure,m_PVC,m_caps);
    maxESC_air(k) = max(Ta(end,1:4));

    p_s.T_ambient_C = p.T_water_C;
    p_s.h_ext = p.h_ext_water;
    [~,Tw] = runThermalCase(p_s,G_ESC_air,G_air_wall,R_cond_enclosure,m_PVC,m_caps);
    maxESC_water(k) = max(Tw(end,1:4));
end

figure('Name','Current sensitivity','Color','w'); %[output:6fb3543a]
plot(currents,maxESC_air,'ro-','LineWidth',1.8,'MarkerFaceColor','r'); hold on; %[output:6fb3543a]
plot(currents,maxESC_water,'bo-','LineWidth',1.8,'MarkerFaceColor','b'); %[output:6fb3543a]
grid on; xlabel('Current per ESC [A]'); ylabel('Maximum ESC temperature at end [°C]'); %[output:6fb3543a]
title('Sensitivity to ESC current'); %[output:6fb3543a]
legend('External air','External water','Location','best'); %[output:6fb3543a]

%%\ LOCAL FUNCTIONS

function [t,T] = runThermalCase(p,G_ESC_air,G_air_wall,R_cond_enclosure,m_PVC,m_caps)
    sigma = 5.670374419e-8; % Stefan-Boltzmann constant [W/m^2-K^4]

    % External convection resistance and total enclosure-to-ambient path
    R_ext_conv = 1/(p.h_ext*p.A_outer_total);
    G_wall_ambient = 1/(R_cond_enclosure + R_ext_conv);

    % Heat generation per ESC
    P_ESC_loss = p.V_batt*p.I_ESC*(1-p.ESC_eff);
    if p.BEC_is_linear
        P_BEC_loss = max(p.V_batt-p.V_BEC,0)*p.I_BEC;
    else
        P_BEC_loss = 0; % enter measured switching-BEC loss separately if needed
    end
    P_each_ESC = P_ESC_loss + P_BEC_loss;

    % State vector: [ESC1 ESC2 ESC3 ESC4 air enclosure] in deg C
    y0 = p.T_initial_C*ones(6,1);
    tspan = [0 p.t_end_min*60];

    opts = odeset('RelTol',1e-6,'AbsTol',1e-7);
    [t,Y] = ode15s(@odefun,tspan,y0,opts);
    T = Y;

    function dYdt = odefun(~,Y)
        Tesc = Y(1:4);
        Tair = Y(5);
        Twall = Y(6);

        % ESC-to-air convection
        Q_ESC_air = G_ESC_air*(Tesc-Tair);

        % ESC-to-wall thermal radiation, exact T^4 expression
        TescK = Tesc+273.15;
        TwallK = Twall+273.15;
        Q_ESC_rad = p.emissivity*sigma*p.A_ESC*(TescK.^4-TwallK.^4);

        % Internal air-to-wall convection
        Q_air_wall = G_air_wall*(Tair-Twall);

        % Energy balances
        dTesc = (P_each_ESC - Q_ESC_air - Q_ESC_rad)/p.C_ESC;
        dTair = (p.P_other_W + sum(Q_ESC_air) - Q_air_wall)/p.C_air;
        dTwall = (sum(Q_ESC_rad) + Q_air_wall - ...
            G_wall_ambient*(Twall-p.T_ambient_C))/(p.C_wall);

        dYdt = [dTesc; dTair; dTwall];
    end
end

function printCaseResults(label,T,p)
    fprintf('\n%s CASE:\n',label);
    fprintf('ESC temperatures: ');
    fprintf('%.2f  ',T(end,1:4));
    fprintf('°C\n');
    fprintf('Internal air: %.2f °C\n',T(end,5));
    fprintf('Enclosure: %.2f °C\n',T(end,6));
end


